import React from "react";
import { useState, useEffect } from "react";
import { useDispatch, useSelector } from "react-redux";
import {
  getDogs,
  chargeAll,
 getTemperaments,
 filterBy
} from "../redux/actions/index";
import { Link } from "react-router-dom";
import Card from "../components/Card";
import Pagination from "../components/Pagination";
import SearchBar from "../components/SearchBar";
import styles from "../styles/Home.module.css";
import { useHistory } from "react-router-dom";

const HomePage = () => {
  const dispatch = useDispatch();
  const history = useHistory();
  //seteamos un estado para poder hacer el refresh de la accion que necesitamos en el select
  const [state, setState] = useState("");
  //para manipular los states
  const allDog = useSelector((state) => state.dogs);
  console.log(allDog);
  //allpokemons2 = useSelector ((state) => state.allPokemons)
  const allTemperaments = useSelector((state) => state.temperaments);

  // Creamos un state con la pagina actual y otro que haga set
  const [currentPage, setCurrentPage] = useState(1);
  const [DogPerPage, setDogPerPage] = useState(8); //asi mostramos 12 por pagina
  const indexLastDog = currentPage * DogPerPage;
  const indexFirstDog = indexLastDog - DogPerPage;
  //para marcar la distancia el slice parte a la mitad.
  const currentDog = allDog.slice(indexFirstDog, indexLastDog);
  //para setear la pagina en ese numero de pagina. Helps with rendering
  const paging = (pageNumber) => {
    setCurrentPage(pageNumber);
  };

  // se va a ejecutar cada vez que ocurra dispatch como en el did mount >// vacio no depende de nada
  useEffect(() => {
    dispatch(getDogs());
    dispatch(getTemperaments());
    const unlisten = history.listen(() => {
      history.go(0);
    });
    return unlisten;
  }, [dispatch, history]);
  

  function handleClick(e) {
    e.preventDefault(); // para que no se rompa. Just in case.
    dispatch(getDogs());
    setCurrentPage(1);
  }

  const handleBy = (e) => {
    dispatch(chargeAll(e.target.value));
  e.target.value = "default";
  }

  function handleByTemperament(e) {
    e.preventDefault();
    dispatch(getTemperaments(e.target.value));
    setCurrentPage(1);
    //setState(e.target.value)
  }
  /*  function handleByName(e) {
    e.preventDefault(); // para que no se rompa. Just in case.
    dispatch();
  } */

  function handleFilter(e) {
    dispatch(filterBy(e.target.value));
    setCurrentPage(1);
  }
  return (
    <div>

      <nav>
        <div className={styles.search}>
          <SearchBar />
        </div>

        <div>
          <Link to="/createDog">
            <button className={styles.btn}>Crear Perrito</button>
          </Link>
        </div>
        </nav>

        <div className={`${styles.filter}`}>
        
        <select onChange={handleBy} name="" id="">
          <option value="default">ordenar por:</option>
          <optgroup className="options" label="Weight">
            <option className="options" value="asc">Max to Min</option>
            <option className="options" value="desc">Min to Max</option>
          </optgroup>
          <optgroup className="options" label="Alphabetic">
            <option className="options" value="A-Z">A - Z</option>
            <option className="options" value="Z-A">Z - A</option>
          </optgroup>
        </select>

      <select className={styles.select} onChange={(e) => handleByTemperament(e)}>
          <option value="All">Tipos de raza</option>
          {allTemperaments.map((temperament) => (
            <option value={temperament.name} key={temperament.name}>
              {temperament.name}
            </option>
          ))}
        </select>

        <select className={styles.select} onChange={(e) => handleFilter(e)}>
          <option value="All">Api / Creados</option>
          <option value="api">api</option>
          <option value="Created">Created</option>
        </select>
      </div>

      {/* cambiamos a current */}
      <div className={`${styles.card} ${styles.cardContainer}`}>
        {/* cambiamos al current para que aparezcan los que quiero */}
        {currentDog.length === 0 ? (
          <img className={styles.image} alt="No hay perritos"></img>
        ) : (
          currentDog.map((c) => {
            return (
              <div className={styles.cardFormat} key={c.id}>
                <Link className={styles.name} to={"/dogs" + c.id}>
                  <Card
                    name={c.name}
                    image={c.image}
                    types={c.types}
                    attack={c.attack}
                  />
                </Link>
              </div>
            );
          })
        )}

       
      </div>

    
      <div className={styles.pagination}>
        <Pagination
          DogPerPage={DogPerPage}
          allDog={allDog.length}
          paging={paging}
        />
      </div>
    </div>
  );
};

export default HomePage;
